  });

  it("leaves malformed/partial image parts untouched", () => {
    expect(normalizeContentPart({ type: "image" })).toEqual({ type: "image" });
    expect(normalizeContentPart({ type: "image", mimeType: "image/png" })).toEqual({
      type: "image",
      mimeType: "image/png",
