      {
        role: "assistant",
        content: [{ type: "toolCall", id: "1", name: "read", arguments: { path: "a.png" } }],
      },
    ] as never);

    expect(out.content).toEqual([
      { type: "tool_call", id: "1", name: "read", args: { path: "a.png" } },
    ]);
  });
});

