      await fs.appendFile(
        "langsmith.jsonl",
        `${JSON.stringify([
          Date.now(),
          eventName,
          arg,
          {
            cwd: ctx.cwd,
            model: ctx.model,
            getContextUsage: ctx.getContextUsage?.(),
          },
        ])}\n`,
      );
    };
  }

  pi.on("resources_discover", createRecord("resources_discover"));
